function requestIdFor(value) {
  let hash = 5381;
  for (const character of value) {
    hash = ((hash << 5) + hash) ^ character.charCodeAt(0);
  }
  return `rushfaster-arrival-${(hash >>> 0).toString(36)}`;
}

function decodeHtml(value) {
  const named = { amp: '&', apos: "'", copy: '©', gt: '>', hellip: '…', lt: '<', nbsp: ' ', quot: '"', reg: '®', rsquo: '’', trade: '™' };
  return value
    .replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, entity) => {
      const key = entity.toLowerCase();
      if (key.startsWith('#x')) return String.fromCodePoint(parseInt(key.slice(2), 16));
      if (key.startsWith('#')) return String.fromCodePoint(parseInt(key.slice(1), 10));
      return named[key] ?? match;
    });
}

function toPlainText(value) {
  return decodeHtml(value
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, '')
    .replace(/<br\s*\/?\s*>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim());
}

function escapeMarkdown(value) {
  return value.replace(/([\\`*_{}[\]<>])/g, '\\$1');
}

function compact(value, maxLength) {
  return value.length <= maxLength ? value : `${value.slice(0, maxLength - 1).trimEnd()}…`;
}

return $input.all().map((item) => {
  const product = item.json;
  const productId = String(product.guid ?? product.id ?? product.link ?? '').trim();
  const title = String(product.title ?? '').trim();
  const productUrl = String(product.link ?? '').trim();
  // Atom feeds expose their HTML item body as summary; RSS feeds use content.
  const summary = String(product.summary ?? product.content ?? product.contentSnippet ?? product.description ?? '').trim();
  const imageUrl = summary.match(/<img\b[^>]*\bsrc=["']([^"']+)/i)?.[1]?.trim() ?? '';
  const price = summary.match(/<strong>\s*Price:\s*<\/strong>\s*([0-9]+(?:[.,][0-9]{2})?)/i)?.[1]?.replace(',', '.') ?? '';
  const descriptionHtml = summary.match(/<td\b[^>]*\bcolspan=["']?2["']?[^>]*>\s*<p[^>]*>([\s\S]*?)<\/p>/i)?.[1] ?? summary;
  const description = compact(toPlainText(descriptionHtml), 700);

  if (!productId || !title || !productUrl || !price || !imageUrl || !description) {
    throw new Error(`Rushfaster feed item is missing required product fields: ${productId || title || productUrl || 'unknown product'}`);
  }

  const published = new Date(product.isoDate ?? product.pubDate ?? '');
  const publishedAt = Number.isNaN(published.valueOf()) ? null : published.toISOString();

  return {
    json: {
      product_id: productId,
      title,
      description,
      price: `$${price} AUD`,
      product_url: productUrl,
      image_url: imageUrl,
      published_at: publishedAt,
      first_seen_at: new Date().toISOString(),
      message: [
        '🆕 **New Rushfaster arrival**',
        '',
        `**${escapeMarkdown(title)}**`,
        '',
        `**Price:** $${price} AUD`,
        '',
        escapeMarkdown(description),
        '',
        `[View product on Rushfaster](${productUrl})`,
      ].join('\n'),
      image_alt: `${title} product image`,
      matrix_request_id: requestIdFor(productId),
    },
  };
});

const product = $('Prepare Rushfaster products').item.json;

return {
  json: {
    product_id: product.product_id,
    title: product.title,
    description: product.description,
    price: product.price,
    product_url: product.product_url,
    image_url: product.image_url,
    published_at: product.published_at,
    first_seen_at: product.first_seen_at,
    matrix_event_id: $json.event_id ?? null,
  },
};
